// Idempotency: check for an open or dispatching restock event for this inventory item
const [existingEvent] = await sql<RestockEventRow[]>`
  SELECT *
  FROM restock_events
  WHERE inventory_item_external_id = ${inventoryItemId}
    AND status IN ('open', 'dispatching')
  LIMIT 1
`;

if (existingEvent) {
  console.log(
    { topic: "inventory_levels/update", inventoryItemId, eventId: existingEvent.id },
    "restock event already open or dispatching, no-op"
  );
  return;
}

